import{_ as a,C as n,c as r,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Convert a lead","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/acquire-leads/convert-lead.md","filePath":"master/sales/crm/acquire-leads/convert-lead.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/acquire-leads/convert-lead.md"};function d(c,e,h,p,m,u){const o=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="convert-a-lead" tabindex="-1">Convert a lead <a class="header-anchor" href="#convert-a-lead" aria-label="Permalink to &quot;Convert a lead&quot;">​</a></h1><p>Converting a lead tells Aureus that the enquiry is real and worth chasing. The lead becomes an opportunity and appears on your pipeline board. You also choose which customer the opportunity belongs to and who owns it.</p><blockquote><p><strong>In simple words:</strong> Convert a lead when you decide to chase the sale. It is the same record, now called an opportunity.</p></blockquote><p>You can convert one lead from its page, or many leads from the list. If Aureus finds duplicates, it can merge them during the conversion.</p><div class="info custom-block"><p class="custom-block-title">About the example</p><p>The lead <strong>ERP implementation for textile manufacturing unit</strong> from Sharma Textiles Pvt. Ltd. is ready. You convert it and give it to yourself.</p></div><h2 id="convert-one-lead" tabindex="-1">Convert one lead <a class="header-anchor" href="#convert-one-lead" aria-label="Permalink to &quot;Convert one lead&quot;">​</a></h2><ol><li>Go to <code>CRM → Leads → Leads</code>.</li><li>Open the lead <strong>ERP implementation for textile manufacturing unit</strong>.</li><li>Click <strong>Convert to Opportunity</strong> in the header.</li><li>In the <strong>Convert to opportunity</strong> window, fill in the fields below.</li><li>Click <strong>Create Opportunity</strong>.</li></ol>',7)),s(o,{src:"/images1/crm/convert-lead-dialog.png",alt:"Convert to opportunity window with Create a new customer chosen, the salesperson and the sales team"}),e[1]||(e[1]=t('<p>You can also use <strong>Convert to Opportunity</strong> in the row menu of the list.</p><h3 id="conversion-action" tabindex="-1">Conversion action <a class="header-anchor" href="#conversion-action" aria-label="Permalink to &quot;Conversion action&quot;">​</a></h3><ul><li><strong><em>Conversion action:</em></strong> Choose <strong>Convert to opportunity</strong> or <strong>Merge with existing opportunities</strong>. This choice shows only when Aureus finds similar leads or opportunities. It starts as <strong>Convert to opportunity</strong>.</li><li><strong><em>Similar leads and opportunities to merge:</em></strong> A list of tick boxes. It shows only after you choose <strong>Merge with existing opportunities</strong>. Required then. All similar records start ticked.</li></ul><p>Each row shows the name, whether it is a lead or an opportunity, the stage (or <strong>Lost</strong>) and the salesperson. See <a href="#merge-similar-records">Merge similar records</a>.</p><h3 id="customer" tabindex="-1">Customer <a class="header-anchor" href="#customer" aria-label="Permalink to &quot;Customer&quot;">​</a></h3><ul><li><strong><em>Customer:</em></strong> Required. Choose one option. <ul><li><strong>Create a new customer:</strong> Aureus adds a contact from the lead data.</li><li><strong>Link to an existing customer:</strong> You pick a contact you already have.</li><li><strong>Do not link to a customer:</strong> The opportunity has no customer yet.</li></ul></li><li><strong><em>Existing Customer:</em></strong> The contact to link. It shows, and is required, only when you choose <strong>Link to an existing customer</strong>. Type to search by name.</li></ul><p>Aureus suggests an option for you. If the lead already has a customer, it picks <strong>Link to an existing customer</strong>. If the lead has a company name or contact name, it picks <strong>Create a new customer</strong>. Otherwise it picks <strong>Do not link to a customer</strong>.</p><p><strong>Example:</strong> Keep <strong>Create a new customer</strong>. Sharma Textiles is not in Contacts yet.</p><h3 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h3><ul><li><strong><em>Salesperson:</em></strong> The owner of the opportunity. It starts as the salesperson on the lead. Only active users of the lead company are listed.</li><li><strong><em>Sales Team:</em></strong> The team that will work the deal. It starts as the team on the lead.</li></ul><p><strong>Example:</strong> Keep yourself as <strong>Salesperson</strong>. Choose the team <strong>Sales</strong>.</p><p>After you click <strong>Create Opportunity</strong>, Aureus shows the message <strong>Converted to opportunity</strong> and opens the opportunity.</p><h2 id="convert-many-leads" tabindex="-1">Convert many leads <a class="header-anchor" href="#convert-many-leads" aria-label="Permalink to &quot;Convert many leads&quot;">​</a></h2><p>Use this when a campaign brought a batch of leads that you want to move together.</p><ol><li>Go to <code>CRM → Leads → Leads</code>.</li><li>Tick the leads you want.</li><li>Open the bulk actions and click <strong>Convert to Opportunities</strong>.</li><li>Fill in the <strong>Convert to opportunities</strong> window.</li><li>Click <strong>Convert</strong>.</li></ol>',15)),s(o,{src:"/images1/crm/convert-lead-mass-dialog.png",alt:"Convert to opportunities window with deduplication on, a salesperson and a sales team chosen"}),e[2]||(e[2]=t('<ul><li><strong><em>Customer:</em></strong> Required. It starts as <strong>Link to an existing customer or create one</strong>. The other options are <strong>Link to an existing customer</strong> and <strong>Do not link to a customer</strong>.</li><li><strong><em>Apply deduplication:</em></strong> On by default. Aureus merges each lead with its similar leads and opportunities, found by the same email, phone or customer.</li><li><strong><em>Salespeople:</em></strong> Pick one or more users. Leads without a salesperson are shared between them in turn.</li><li><strong><em>Force assignment:</em></strong> Also reassign leads that already have a salesperson.</li><li><strong><em>Sales Team:</em></strong> Put every converted lead in this team. Leave it empty to keep each lead&#39;s own team.</li></ul><p>When the customer option links to an existing customer, Aureus looks for a contact with the same email address. If it finds none and you chose to create one, it adds a new contact.</p><p>When it finishes, a message tells you how many leads were converted, how many similar records were merged, and how many were skipped. Rows that are not open leads are skipped.</p><h2 id="merge-similar-records" tabindex="-1">Merge similar records <a class="header-anchor" href="#merge-similar-records" aria-label="Permalink to &quot;Merge similar records&quot;">​</a></h2><p>Two records are similar when they belong to the same company and share an email address, a phone number or a customer. Phone numbers are compared by their digits.</p><p>The <strong>Similar Leads</strong> tab on a lead lists them. You can merge in two ways.</p><ul><li>During conversion, choose <strong>Merge with existing opportunities</strong> and tick the records to join.</li><li>From the <strong>Leads</strong> list, tick two or more rows and click <strong>Merge</strong>.</li></ul><p>The <strong>Merge similar leads and opportunities</strong> window has these fields.</p><ul><li><strong><em>Records to merge:</em></strong> A table with the name, type, stage, email and salesperson of each record. Remove a row to leave that record out. At least two must remain.</li><li><strong><em>Record to keep:</em></strong> The record whose details stay. Required. Aureus suggests one.</li><li><strong><em>Salesperson</em></strong> and <strong><em>Sales Team:</em></strong> They appear only when the records have different values. Choose the one the merged record keeps.</li></ul><p>Empty fields of the kept record are filled from the others. Their notes, tags, messages, activities and attachments move to it. The other records are then deleted. The result is an opportunity if any of them was one, and it is active even if some were lost. A note in <strong>Chatter</strong> lists what was merged.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You must be allowed to edit the kept record and to delete the others. Only records of the same company can be merged.</p></div><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>The record type changes from <strong>Lead</strong> to <strong>Opportunity</strong>. It is the same record, so notes, activities and tags stay.</li><li>The opportunity appears on the pipeline board in <code>CRM → Sales → My Pipeline</code>. See <a href="./../pipeline/manage-opportunities.html">Manage opportunities</a>.</li><li>The conversion date is stored on the record.</li><li><strong>Create a new customer</strong> adds a contact. For a company lead, the contact is a company named after <strong>Company Name</strong>. Otherwise it is a person named after the contact or the lead. The email, phone, website, address and country are copied.</li><li>The lead disappears from the <strong>Leads</strong> list. It shows in the pipeline instead.</li><li>Automatic assignment can also convert a lead for you. When a team uses opportunities and a salesperson receives a lead, Aureus converts it without creating a customer. See <a href="./../assign-and-track/">Assign and track</a>.</li></ul><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Create Opportunity</strong></td><td>Converts the lead and opens the opportunity.</td></tr><tr><td><strong>Convert</strong></td><td>Converts all ticked leads in the bulk window.</td></tr><tr><td><strong>Merge</strong></td><td>Joins the records you chose into one.</td></tr><tr><td><strong>Cancel</strong></td><td>Closes the window. The lead stays as it is.</td></tr></tbody></table><p>If the lead is not worth chasing, click <strong>Lost</strong> on the lead instead. See <a href="./create-lead.html#actions-and-statuses">Create a lead</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Choose <strong>Link to an existing customer</strong> when the company is already in Contacts. It avoids duplicate contacts.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A lead with a probability of 100 % cannot be converted. You see the message <strong>A lead at 100% probability cannot be converted. Lower its probability first.</strong></p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-lead.html">Create a lead</a></li><li><a href="./../pipeline/manage-opportunities.html">Manage opportunities</a></li><li><a href="./../pipeline/create-quotation.html">Create a quotation</a></li><li><a href="./../../../getting-started/contacts/contacts.html">Contacts</a></li></ul>',20))])}const w=a(l,[["render",d]]);export{y as __pageData,w as default};
